WITH metrics_long AS (SELECT * FROM (SELECT id, device_code, temp_c, humidity, pressure FROM device_readings) src UNPIVOT (value FOR kpi IN (temp_c, humidity AS HUMIDITY, pressure AS PRESSURE))) SELECT kpi, CASE WHEN value >= 90 THEN 'PREMIUM' ELSE 'STANDARD' END AS value_tier, APPROX_PERCENTILE(value, ARRAY(0.25, 0.5, 0.75)) AS value_quartiles, ROUND(AVG(value), 2) AS avg_value, COUNT(*) FILTER (WHERE device_code = 'DV-01') AS dv_01_rows, MIN(value) AS min_value, GROUPING_ID() AS grouping_id FROM metrics_long GROUP BY GROUPING SETS ((kpi, CASE WHEN value >= 90 THEN 'PREMIUM' ELSE 'STANDARD' END), (kpi), ()) ORDER BY value_tier DESC
